const FRASES_FINALIZACAO = [
  'Fechamos seu pedido',
  'O time técnico vai analisar a disponibilidade',
  'nossa equipe entrará em contato em breve para confirmar',
  'O seu pedido será analisado',
  'a primeira fatura vem só no próximo mês',
  'link por email e WhatsApp',
  'Seu pedido foi registrado com sucesso',
  'Pronto, registrei tudo aqui',
  'Teu pedido já ta registrado aqui',
  'a gente vai entrar em contato',
  'vai receber um link',
  'aceitar os termos e fechar o pedido',
  'Então seu pedido está tudo certo' //FRASES B2C ATIVO ADICIONAR CONFORME NECESSIDADE, AS FRASES ACIMA SÃO VÁLIDAS PARA OS DEMAIS PROJETOS
];

const items = $input.all();
const conversasFinalizadas = [];

for (const item of items) {
  const transcript = item.json.transcript;

  // ✅ transcript é um array de objetos {role, message}
  const todasMensagens = Array.isArray(transcript)
    ? transcript.map(t => t.message || '').join(' ')
    : String(transcript || '');

  const foiFinalizado = FRASES_FINALIZACAO.some(frase =>
    todasMensagens.toLowerCase().includes(frase.toLowerCase())
  );

  if (foiFinalizado) {
    conversasFinalizadas.push(item);
  }
}

// Se nenhuma conversa foi finalizada, retorna array vazio com flag
return conversasFinalizadas.length > 0
  ? conversasFinalizadas
  : [{ json: { nenhuma_finalizada: true } }];

// =====================================================
// FUNÇÕES UTILITÁRIAS
// =====================================================

function formatarData(dataString) {
  if (!dataString) return 'N/A';

  const data = new Date(dataString);

  if (isNaN(data.getTime())) {
    return 'N/A';
  }

  return data.toLocaleString('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit'
  });
}


// =====================================================
// REPARAÇÃO DE ENCODING
// =====================================================

function repararEncoding(texto) {
  if (texto === undefined || texto === null) {
    return '';
  }

  const mapa = {
    '茅': 'e',
    '莽': 'c',
    '茫': 'a',
    '煤': 'u',
    '铆': 'i',
    '谩': 'a',
    '锚': 'e',
    '么': 'o',
    '脡': 'E',
    '脿': 'a',
    '玫': 'o',
    '莽玫': 'co',
    '脰': 'O',
    '盲': 'a',
    '枚': 'o',
    '茂': 'i',
    '芒': 'a',
    '讲': '',
    '鈥': '-'
  };

  let resultado = String(texto);

  for (const [corrompido, correto] of Object.entries(mapa)) {
    resultado = resultado.split(corrompido).join(correto);
  }

  return resultado;
}


// =====================================================
// NORMALIZAÇÃO DE TEXTO
// =====================================================

function normalizarTexto(texto) {
  if (texto === undefined || texto === null) {
    return '';
  }

  return repararEncoding(texto)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}


// =====================================================
// VERIFICA SE UM VALOR FOI REALMENTE INFORMADO
// =====================================================

function valorFoiInformado(valor) {
  if (valor === undefined || valor === null) {
    return false;
  }

  const texto = normalizarTexto(valor);

  return ![
    '',
    'null',
    'undefined',
    'n/a',
    'na',
    'nao informado',
    'nao informada',
    'nao informado(a)',
    'nao fornecido',
    'nao fornecida',
    'nao localizado',
    'nao localizada',
    'nao encontrado',
    'nao encontrada'
  ].includes(texto);
}


// =====================================================
// OBTÉM O VALOR REAL DO CAMPO NO INTENDED GEMINI
// =====================================================
//
// Alguns nomes usados no monitoramento são diferentes
// dos nomes usados pelo intendedGemini.
//
// Exemplo:
//
// numero_portabilidade
//       ↓
// telefone_portabilidade
//
// qtd_linhas_port
//       ↓
// quantidade_linhas
//
// qtd_linhas_nova
//       ↓
// quantidade_linhas
// =====================================================

function obterValorCampo(campo, gemini) {

  const MAPA_CAMPOS = {
    'numero_portabilidade': 'telefone_portabilidade',
    'qtd_linhas_port': 'quantidade_linhas',
    'qtd_linhas_nova': 'quantidade_linhas'
  };

  const campoReal = MAPA_CAMPOS[campo] || campo;

  return gemini[campoReal];
}


// =====================================================
// RESOLVER VALOR DO NOME
// =====================================================

function resolverValor(campo, gemini, dadosN8n) {

  if (campo === 'nome') {

    const valores = [
      dadosN8n.nomeChamada,
      dadosN8n.nomeApi,
      gemini.nome
    ];

    for (const valor of valores) {

      if (valor === undefined || valor === null) {
        continue;
      }

      const texto = normalizarTexto(valor);

      if (
        texto !== '' &&
        texto !== 'nao informado' &&
        texto !== 'null' &&
        texto !== 'undefined'
      ) {
        return valor;
      }
    }

    return null;
  }

  return gemini[campo] ?? null;
}


// =====================================================
// PERGUNTAS POR CAMPO
// =====================================================
//
// IMPORTANTE:
// As palavras estão propositalmente sem acentos,
// pois normalizarTexto() também remove acentos.
//
// =====================================================

const PERGUNTAS_POR_CAMPO = {

  // ---------------------------------------------------
  // NOME
  // ---------------------------------------------------
  'nome': [
    ['quem', 'falo'],
    ['seu', 'nome'],
