    ['me', 'fala', 'seu', 'nome'],
    ['me', 'passa', 'seu', 'nome']
  ],


  // ---------------------------------------------------
  // CEP
  // ---------------------------------------------------
  'cep': [
    ['cep'],
    ['codigo', 'postal'],
    ['me', 'passa', 'cep'],
    ['me', 'fala', 'cep'],
    ['qual', 'cep']
  ],


  // ---------------------------------------------------
  // ENDEREÇO
  // ---------------------------------------------------
  'endereco': [
    ['endereco'],
    ['endereco', 'completo'],
    ['rua', 'numero'],
    ['rua', 'instalacao'],
    ['numero', 'instalacao'],
    ['local', 'instalacao'],
    ['endereco', 'instalacao'],
    ['numero', 'complemento'],
    ['rua', 'complemento'],
    ['logradouro', 'numero'],
    ['logradouro'],
    ['qual', 'endereco'],
    ['me', 'fala', 'rua'],
    ['me', 'passa', 'rua'],
    ['me', 'fala', 'endereco'],
    ['me', 'passa', 'endereco'],
    ['qual', 'rua']
  ],


  // ---------------------------------------------------
  // SKU / PLANO
  // ---------------------------------------------------
  'sku': [
    ['plano'],
    ['mega'],
    ['giga'],
    ['qual', 'plano'],
    ['plano', 'escolhido'],
    ['qual', 'plano', 'voce', 'quer'],
    ['qual', 'plano', 'voce', 'deseja'],
    ['me', 'fala', 'plano'],
    ['me', 'passa', 'plano']
  ],


  // ---------------------------------------------------
  // CPF
  // ---------------------------------------------------
  'cpf': [
    ['cpf'],
    ['numero', 'cpf'],
    ['seu', 'cpf'],
    ['me', 'passa', 'cpf'],
    ['me', 'fala', 'cpf']
  ],


  // ---------------------------------------------------
  // EMAIL
  // ---------------------------------------------------
  'email': [
    ['email'],
    ['e-mail'],
    ['seu', 'email'],
    ['me', 'passa', 'email'],
    ['me', 'fala', 'email']
  ],


  // ---------------------------------------------------
  // DIA DE VENCIMENTO
  // ---------------------------------------------------
  'dia_vencimento': [
    ['vencimento'],
    ['dia', 'fatura'],
    ['dia', 'vencimento'],
    ['qual', 'dia', 'vencimento'],
    ['qual', 'dia', 'fatura'],
    ['dia', 'voce', 'prefere'],
    ['qual', 'data', 'vencimento']
  ],


  // ---------------------------------------------------
  // DATA DE INSTALAÇÃO
  // ---------------------------------------------------
  'data_instalacao': [
    ['instalacao'],
    ['data', 'instalacao'],
    ['data', 'turno'],
    ['dia', 'instalacao'],
    ['qual', 'data', 'instalacao'],
    ['quando', 'instalar'],
    ['quando', 'sera', 'instalacao']
  ],


  // ---------------------------------------------------
  // TIPO DE ATENDIMENTO
  // ---------------------------------------------------
  'tipo_de_atendimento': [
    ['tipo', 'atendimento'],
    ['migracao'],
    ['portabilidade'],
    ['nova', 'linha'],
    ['trazer', 'numero'],
    ['outra', 'operadora'],
    ['ja', 'tem', 'vivo'],
    ['vai', 'trazer', 'numero'],
    ['quer', 'trazer', 'numero']
  ],


  // ---------------------------------------------------
  // NÚMERO VIVO
  // ---------------------------------------------------
  'numero_vivo': [
    ['numero', 'vivo'],
    ['seu', 'numero'],
    ['telefone', 'vivo'],
    ['numero', 'telefone'],
    ['qual', 'numero', 'vivo'],
    ['me', 'passa', 'numero', 'vivo'],
    ['me', 'fala', 'numero', 'vivo']
  ],


  // ---------------------------------------------------
  // NÚMERO DA PORTABILIDADE
  // ---------------------------------------------------
  //
  // NÃO usamos:
  //
  // ['portabilidade']
  // ['portar']
  //
  // porque são palavras genéricas demais.
  //
  // ---------------------------------------------------
  'numero_portabilidade': [
    ['numero', 'trazer'],
    ['numero', 'portar'],
    ['numero', 'ddd'],
    ['numero', 'portabilidade'],
    ['qual', 'numero'],
    ['me', 'passa', 'numero'],
    ['me', 'fala', 'numero'],
    ['informe', 'numero'],
    ['informa', 'numero'],
    ['digite', 'numero']
  ],


  // ---------------------------------------------------
  // CNPJ
  // ---------------------------------------------------
  'cnpj': [
    ['cnpj'],
    ['cnpj', 'empresa'],
    ['numero', 'cnpj'],
    ['seu', 'cnpj'],
    ['me', 'passa', 'cnpj'],
    ['me', 'fala', 'cnpj']
  ],


  // ---------------------------------------------------
  // QUANTIDADE DE LINHAS - NOVA LINHA
  // ---------------------------------------------------
  'qtd_linhas_nova': [
    ['quantas', 'linhas'],
    ['linhas', 'contratar'],
    ['quantas', 'contratar'],
    ['linhas', 'novas'],
    ['nova', 'linha'],
    ['quer', 'contratar'],
    ['quantidade', 'linhas'],
    ['quantas', 'linhas', 'quer'],
    ['quantas', 'linhas', 'deseja'],
    ['quantas', 'linhas', 'vai']
  ],


  // ---------------------------------------------------
  // QUANTIDADE DE LINHAS - PORTABILIDADE
  // ---------------------------------------------------
  'qtd_linhas_port': [
    ['quais', 'numeros', 'quer', 'trazer'],
    ['quantas', 'linhas'],
    ['quantas', 'linhas', 'trazer'],
    ['quantas', 'linhas', 'portabilidade'],
    ['quantas', 'linhas', 'portar'],
    ['quantidade', 'linhas'],
    ['quantas', 'linhas', 'quer'],
    ['quantas', 'linhas', 'deseja'],
    ['quantas', 'linhas', 'vai', 'trazer'],
    ['quantas', 'linhas', 'vai', 'portar']
  ]
};


// =====================================================
// VERIFICA SE UMA PERGUNTA FOI FEITA
// =====================================================

function perguntaFoiFeita(transcript, palavrasChave) {

  if (!Array.isArray(transcript)) {
    return false;
  }

  const mensagensAgente = transcript
    .filter(t => t && t.role === 'agent')
    .map(t => normalizarTexto(t.message || ''))
    .filter(Boolean);

  const palavrasNormalizadas = palavrasChave.map(palavra =>
    normalizarTexto(palavra)
  );

  return mensagensAgente.some(mensagem =>
    palavrasNormalizadas.every(palavra =>
      mensagem.includes(palavra)
    )
  );
}


// =====================================================
// VERIFICA TODAS AS VARIAÇÕES DE UMA PERGUNTA
// =====================================================

function verificarPergunta(transcript, campo) {

  const conjuntos = PERGUNTAS_POR_CAMPO[campo];

  if (!conjuntos) {
    return false;
  }

  return conjuntos.some(palavrasChave =>
    perguntaFoiFeita(transcript, palavrasChave)
  );
}


// =====================================================
// OBTÉM TODOS OS ITEMS DE ENTRADA
// =====================================================

const items = $input.all();


// =====================================================
// PROTEÇÃO CONTRA RETORNO ESPECIAL DO NODE ANTERIOR
// =====================================================

if (
  items.length > 0 &&
  items.every(item =>
    item &&
    item.json &&
    (
      item.json.nenhum_novo === true ||
      item.json.nenhuma_finalizada === true
    )
  )
) {
  return items;
}


// =====================================================
// RESULTADO
// =====================================================

const resultado = [];


// =====================================================
// AGENTES B2B
// =====================================================

const AGENTES_B2B = [
  'agent_EXEMPLO_06',
  'agent_EXEMPLO_03',
  'agent_EXEMPLO_02',
  'agent_EXEMPLO_07',
  'agent_EXEMPLO_05',
  'agent_EXEMPLO_04'
];


// =====================================================
// PROCESSAMENTO DE CADA CONVERSA
// =====================================================

for (const item of items) {

  const dados = item.json || {};

  const gemini = dados.intendedGemini || {};

  const dadosN8n = dados.dados_n8n || {};

  const transcript = Array.isArray(dados.transcript)
    ? dados.transcript
    : [];

  const agentId =
    dados.agentId ||
    dadosN8n.agentId ||
    '';

  const produto =
    String(dadosN8n.product || gemini.produto || '')
      .toUpperCase()
      .trim();

  const tipoAtendimento =
    String(gemini.tipo_de_atendimento || '')
      .toLowerCase()
      .trim();


  // ===================================================
  // PEDIDO CONCLUÍDO
  // ===================================================

  const pedidoConcluido =
    normalizarTexto(dadosN8n.pedidoconcluido || '') === 'sim';


  // ===================================================
  // CAMPOS OBRIGATÓRIOS
  // ===================================================

  let camposObrigatorios = [];


  // ===================================================
  // PORTABILIDADE B2B
  // ===================================================

  if (
    produto === 'PORTABILIDADE' &&
    AGENTES_B2B.includes(agentId)
  ) {

    camposObrigatorios = [
      {
        campo: 'nome',
        label: 'Nome'
      },
      {
        campo: 'sku',
        label: 'Plano (SKU)'
      },
      {
        campo: 'qtd_linhas_port',
        label: 'Qtd Linhas Portabilidade'
      },
      {
        campo: 'numero_portabilidade',
        label: 'Número da Portabilidade'
      },
      {
        campo: 'cnpj',
        label: 'CNPJ'
      },
      {
        campo: 'cpf',
        label: 'CPF'
      },
      {
        campo: 'email',
        label: 'E-mail'
      }
    ];


    // -------------------------------------------------
    // AGENTE 6301
    // NÃO EXIGE NOME
    // -------------------------------------------------

    if (
      agentId ===
      'agent_EXEMPLO_07'
    ) {

      camposObrigatorios =
        camposObrigatorios.filter(
          campo => campo.campo !== 'nome'
        );
    }
  }


  // ===================================================
  // NOVA LINHA B2B
  // ===================================================

  else if (
    produto === 'NOVA LINHA' &&
    AGENTES_B2B.includes(agentId)
  ) {

    camposObrigatorios = [
      {
        campo: 'nome',
        label: 'Nome'
      },
      {
        campo: 'sku',
        label: 'Plano (SKU)'
      },
      {
        campo: 'qtd_linhas_nova',
        label: 'Qtd Linhas Nova Linha'
      },
      {
        campo: 'cnpj',
        label: 'CNPJ'
      },
      {
        campo: 'cpf',
        label: 'CPF'
      },
      {
        campo: 'email',
        label: 'E-mail'
      }
    ];


    // -------------------------------------------------
    // AGENTE 6301
    // NÃO EXIGE NOME
    // -------------------------------------------------

    if (
      agentId ===
      'agent_EXEMPLO_07'
    ) {

      camposObrigatorios =
        camposObrigatorios.filter(
          campo => campo.campo !== 'nome'
        );
    }
  }


  // ===================================================
  // VIVO FIBRA / VIVO TOTAL
  // ===================================================

  else if (
    produto === 'VIVO FIBRA' ||
    produto === 'VIVO TOTAL'
  ) {

    camposObrigatorios = [
      {
        campo: 'sku',
        label: 'Plano (SKU)'
      },
      {
        campo: 'cep',
        label: 'CEP'
      },
      {
        campo: 'endereco',
        label: 'Endereço'
      },
      {
        campo: 'cpf',
        label: 'CPF'
      },
      {
        campo: 'dia_vencimento',
        label: 'Dia de Vencimento'
      },
      {
        campo: 'email',
        label: 'E-mail'
      },
      {
        campo: 'data_instalacao',
        label: 'Data de Instalação'
      }
    ];


    // -------------------------------------------------
    // AGENTE RECEPTIVO
    // EXIGE NOME
    // -------------------------------------------------

    if (
      agentId ===
      'agent_EXEMPLO_01'
    ) {

      camposObrigatorios.unshift({
        campo: 'nome',
        label: 'Nome'
      });
    }


    // -------------------------------------------------
    // VIVO TOTAL
    // -------------------------------------------------

    if (produto === 'VIVO TOTAL') {

      camposObrigatorios.push({
        campo: 'tipo_de_atendimento',
        label: 'Tipo de Atendimento'
      });


      // -----------------------------------------------
      // MIGRAÇÃO
      // -----------------------------------------------

      if (
        tipoAtendimento.includes('migracao')
      ) {

        camposObrigatorios.push({
          campo: 'numero_vivo',
          label: 'Número Vivo'
        });
      }


      // -----------------------------------------------
      // PORTABILIDADE
      // -----------------------------------------------

      else if (
        tipoAtendimento.includes('portabilidade')
      ) {

        camposObrigatorios.push({
          campo: 'numero_portabilidade',
          label: 'Número da Portabilidade'
        });
      }
    }
  }


  // ===================================================
  // PRODUTO FORA DO ESCOPO
  // ===================================================

  else {
    continue;
  }


  // ===================================================
  // VERIFICAÇÃO DOS CAMPOS
  // ===================================================

  const faltando = [];

  const detalhes = [];


  for (
    const { campo, label }
    of camposObrigatorios
  ) {

    // -----------------------------------------------
    // A IA perguntou?
    // -----------------------------------------------

    const perguntou =
      verificarPergunta(
        transcript,
        campo
      );


    // -----------------------------------------------
    // Qual é o valor real no Gemini?
    // -----------------------------------------------

    const valor =
      obterValorCampo(
        campo,
        gemini
      );


    // -----------------------------------------------
    // O valor foi informado?
    // -----------------------------------------------

    const informado =
      valorFoiInformado(valor);


    // =================================================
    // CASO 1
    // IA NÃO PERGUNTOU
    // =================================================

    if (!perguntou) {

      faltando.push(label);


      if (!informado) {

        detalhes.push(
          `${label}: IA não perguntou e dado não informado`
        );

      } else {

        detalhes.push(
          `${label}: IA não perguntou`
        );
      }

      continue;
    }


    // =================================================
    // CASO 2
    // IA PERGUNTOU, MAS DADO NÃO FOI INFORMADO
    // =================================================

    if (!informado) {

      faltando.push(label);

      detalhes.push(
        `${label}: IA perguntou, mas dado não informado`
      );

      continue;
    }


    // =================================================
    // CASO 3
    // IA PERGUNTOU + DADO INFORMADO
    // =================================================
    //
    // Campo considerado correto.
    //
    // Não fazemos nada.
    //
  }


  // ===================================================
  // ADICIONA RESULTADO
  // ===================================================

  resultado.push({

    json: {

      conversationId:
        dados.conversationId,

      id_registro:
        dados.id,

      pedido_concluido:
        dadosN8n.pedidoconcluido || 'N/A',

      nome_cliente:
        resolverValor(
          'nome',
          gemini,
          dadosN8n
        ) || 'Não identificado',

      agente_id:
        agentId,

      produto:
        produto,

      tipo_atendimento:
        tipoAtendimento || 'N/A',

      campos_faltando:
        faltando.join(', '),

      detalhes:
        detalhes.join(' | '),

      total_faltando:
        faltando.length,

      tem_pendencia:
        faltando.length > 0,

      data_conversa:
        formatarData(
          dados.createdAt
        ),

      link_conversa:
        `https://app.elevenlabs.io/conversational-ai/conversations/${dados.conversationId}`,

      verificado_em:
        new Date().toLocaleString(
          'pt-BR',
          {
            timeZone: 'America/Sao_Paulo'
          }
        )
    }
  });
}


// =====================================================
// RETORNO
// =====================================================
//
// IMPORTANTE:
// O Code Node precisa retornar um array de items,
// cada um contendo { json: {...} }.
// =====================================================

return resultado.length > 0
  ? resultado
  : [
      {
        json: {
          sem_pendencias: true,
          total_verificados: items.length
        }
      }
    ];

